import {nf,frontier,freight,gdp,trade,exportsData} from './models.js';
const $=s=>document.querySelector(s);
const evidenceDraft={};
const sources={pib:'https://www.dane.gov.co/files/operaciones/PIB/cp-PIB-IItrim2026.pdf',expo:'https://www.dane.gov.co/files/operaciones/EXPORTACIONES/bol-EXPORTACIONES-jul2026.pdf',omc:'https://www.wto.org/english/news_e/news26_e/rese_31jul26_469_e.htm',gtos:'https://www.wto.org/english/res_e/publications_e/gtos0326_e.htm',unctad:'https://unctad.org/topic/transport-and-trade-logistics/review-of-maritime-transport',core:'https://books.core-econ.org/the-economy-v1/book/es/text/0-3-contents.html',manual:'https://drive.google.com/file/d/1XnZlzgVXcjbhNEUDjySarGD-PCB2i5YM/view'};
const link=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗<span class="sr-only"> (abre una nueva pestaña)</span></a>`;
const source=(key,label)=>`<p class="source-link">${link(sources[key],label)}</p>`;
const hero=(num,title,desc,date)=>`<div class="eyebrow">${num}</div><h1>${title}</h1><p class="intro">${desc}</p><div class="meta"><span>${date}</span><span>Fundamentos de Economía y Comercio</span><span>Lee · experimenta · argumenta</span></div>`;
const note=text=>`<div class="note">${text}</div>`;
const details=(title,text)=>`<details><summary>${title}</summary><p>${text}</p></details>`;
const table=(head,rows,caption='')=>`<div class="table-wrap"><table>${caption?`<caption>${caption}</caption>`:''}<thead><tr>${head.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function quiz(id,question,options,answer,explain){return `<form class="quiz" data-answer="${answer}" data-explanation="${explain.replaceAll('"','&quot;')}"><fieldset><legend>${question}</legend>${options.map((o,i)=>`<label class="option"><input type="radio" name="${id}" value="${i}" required><span>${o}</span></label>`).join('')}</fieldset><button class="btn" type="submit">Comprobar mi respuesta</button><div class="feedback" role="status" aria-live="polite"></div></form>`;}
const slider=(id,label,min,max,value,step=1,suffix='')=>`<div class="control"><label for="${id}">${label}<output id="${id}-label" for="${id}">${value}${suffix}</output></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><div class="range-labels"><span>${min}${suffix}</span><span id="${id}-max">${max}${suffix}</span></div></div>`;

function session2(){return hero('Sesión 02 / 11 septiembre 2026','Cada elección tiene una alternativa.','¿Qué sacrificas cuando decides? Experimenta con los recursos de una empresa y descubre por qué el costo de una decisión va más allá del dinero.','Resultado: justificar una elección')+`
<span class="tag sim">Caso simulado · Pacífico Cacao</span><p>Una empresa ficticia del Valle del Cauca prepara cacao y chocolate para vender. Cada lote de cacao requiere <strong>2 horas</strong>; cada lote de chocolate, <strong>4 horas</strong>. Cambia las horas disponibles y observa sus posibilidades.</p>
<div class="lab"><div class="controls"><span class="index">EXPERIMENTO 01</span><h2>Un tiempo limitado.<br>Dos productos.</h2><p>Todo el tiempo se asigna a producir. Para obtener más chocolate debes renunciar a cacao.</p>${slider('hours','Horas disponibles',60,180,120,4,' h')}${slider('chocolate','Lotes de chocolate',0,30,15)}<div class="result" id="frontier-result" aria-live="polite"></div><button type="button" class="btn secondary" id="reset-frontier">Restablecer escenario</button></div><div class="viz"><div class="eyebrow">Frontera de posibilidades de producción</div><svg viewBox="0 0 520 320" role="img" aria-labelledby="fpp-title fpp-desc"><title id="fpp-title">Frontera de cacao y chocolate</title><desc id="fpp-desc"></desc><g stroke="#52616c" stroke-width="1"><path d="M65 35V260H485"/><path d="M65 90H485M65 145H485M65 200H485" stroke-dasharray="3 6"/></g><g fill="#d9dce1" font-family="Arial" font-size="13"><text x="65" y="22">Chocolate (lotes)</text><text x="370" y="309">Cacao (lotes)</text><text x="43" y="265">0</text><text x="186" y="280">30</text><text x="321" y="280">60</text><text x="455" y="280">90</text><text x="35" y="187">15</text><text x="35" y="112">30</text><text x="35" y="39">45</text></g><path id="frontier-area" fill="#ffffff" opacity=".07"/><path id="frontier-line" fill="none" stroke="#e99ba2" stroke-width="3"/><path id="frontier-guide" fill="none" stroke="#d5dce1" stroke-dasharray="4 4"/><circle id="frontier-dot" r="7" fill="white" stroke="#e99ba2" stroke-width="3"/></svg><div class="stat-row"><div class="stat"><b id="cacao-result">30</b><span>lotes de cacao</span></div><div class="stat"><b id="choco-result">15</b><span>lotes de chocolate</span></div></div><p class="caption">Cada punto de la línea usa todas las horas. Debajo hay capacidad sin utilizar; encima se necesitan más recursos o productividad.</p></div></div>
<p class="caption">Modelo: 2C + 4H ≤ horas disponibles. Productividad constante, trabajo divisible y una sola restricción. Elaboración didáctica; no son datos de empresas reales.</p>
<section class="section"><span class="index">ANTES DE SEGUIR</span><h2>Cuatro ideas para mirar una decisión</h2><div class="two-col"><div>${details('Escasez','Los recursos disponibles no permiten realizar todas las alternativas deseadas. Puede faltar tiempo, capacidad, información o presupuesto. Escasez no es sinónimo de pobreza.')}${details('Costo de oportunidad','Es el valor de la mejor alternativa sacrificada. En este modelo, producir un chocolate exige renunciar a dos lotes de cacao. No se suman todas las alternativas descartadas.')}</div><div>${details('Preferencias y restricciones','Una preferencia expresa qué valoras; una restricción limita lo que puedes hacer. Preferir rapidez no hace que desaparezca el presupuesto disponible.')}${details('Pensamiento marginal','Compara el beneficio y el costo de una unidad adicional. Incluye el uso alternativo de los recursos y evita contar dos veces el mismo costo.')}</div></div>
${quiz('q-fpp','Con 120 horas, ¿es posible producir 40 lotes de cacao y 15 de chocolate?',['Sí, porque ambos productos son rentables.','No: esa combinación requiere 140 horas.','Sí: se necesitan solo 110 horas.'],1,'40 × 2 + 15 × 4 = 140 horas. La combinación supera en 20 horas los recursos disponibles. Ser rentable no la hace factible.')}</section>
<section class="section"><span class="index">EXPERIMENTO 02</span><h2>¿El flete más barato es la mejor opción?</h2><p>Para el mismo envío, A cobra USD 1.200 y tarda 20 días; B cobra USD 1.650 y tarda 12. La calidad y confiabilidad se suponen iguales. Ajusta el costo diario de mantener el inventario.</p><div class="lab"><div class="controls">${slider('daily','Costo de inventario por día',0,150,70,1,' USD')}<p>Costo total = flete + días × costo diario.</p><div class="result" id="freight-result" aria-live="polite"></div></div><div class="viz"><span class="eyebrow">Comparación del costo total · USD</span><div class="stat-row"><div class="stat"><b id="freight-a"></b><span>Opción A · 20 días</span></div><div class="stat"><b id="freight-b"></b><span>Opción B · 12 días</span></div></div><p>La decisión cambia cuando el costo diario supera USD 56,25. El tiempo también es un recurso.</p></div></div>${note('<strong>Piensa en un contraejemplo.</strong> ¿Qué ocurre si B tiene más retrasos? El modelo no contempla esa diferencia. Necesitarías información sobre frecuencia y costo de las demoras.')}
<div class="concept-grid"><article class="concept"><h3>Anclaje</h3><p>La primera cotización puede convertirse en una referencia arbitraria. Compara condiciones equivalentes.</p></article><article class="concept"><h3>Statu quo</h3><p>Renovar automáticamente al proveedor habitual evita revisar alternativas. Programa una comparación periódica.</p></article><article class="concept"><h3>Exceso de confianza</h3><p>“Nunca nos retrasamos” es una creencia que debe contrastarse con registros de entregas.</p></article></div></section>
<section class="section"><span class="index">AMPLÍA LA MIRADA</span><h2>La economía también cambia sus preguntas</h2>${table(['Enfoque','Pregunta que aporta','Aplicación al comercio'],[['Clásico · Smith y Ricardo','¿Cómo surgen riqueza y especialización?','División del trabajo y costos relativos.'],['Marxista','¿Quién controla la producción y recibe el excedente?','Propiedad, salarios y negociación.'],['Marginalista','¿Qué cambia con una unidad adicional?','Comparación de beneficios y costos.'],['Keynesiano','¿Cómo influye el gasto agregado en el empleo?','Pedidos, producción y ocupación.'],['Institucional','¿Cómo condicionan las reglas las decisiones?','Contratos, crédito y confianza.'],['Conductual','¿Cómo decidimos con información y atención limitadas?','Sesgos y arquitectura de elección.']])}<p class="caption">Mapa de preguntas basado en los enfoques de S2. Las perspectivas conviven; no se presentan como una sustitución lineal.</p>${note('<strong>Hecho, hipótesis o valoración.</strong> “El envío B tarda 12 días” es un dato del caso. “Una demora reducirá ventas” es una hipótesis. “Debemos priorizar el empleo local” es una valoración que requiere razones.')}<p><strong>Lectura del programa:</strong> Mankiw, capítulos 1 y 2; Thaler y Sunstein, introducción y capítulos 1 y 5. ${link(sources.core,'Complementa con CORE: elección y costo de oportunidad')}</p><a class="btn" href="#sesion-3">Continuar a producción y flujos →</a></section>`;}

function session3(){return hero('Sesión 03 / 18 septiembre 2026','Una empresa nunca produce sola.','Explora cómo el trabajo, los recursos y los pagos conectan a hogares, empresas, Estado y resto del mundo. Después, interpreta qué mide el PIB.','Resultado: relacionar producción e ingresos')+`
<div class="lab"><div class="controls"><span class="index">EXPERIMENTO 03</span><h2>Sigue el recorrido<br>de un intercambio.</h2><p>Selecciona una relación para distinguir lo que se entrega y cómo se paga. Los flujos reales incluyen bienes y servicios; los monetarios incluyen dinero.</p><div class="note"><strong>El caso conductor</strong><p>Pacífico Cacao contrata trabajo, importa una máquina y exporta chocolate. Selecciona cada actor y sigue la relación.</p></div><p class="caption">Esquema de economía abierta simplificado. No todos los pagos tienen una contraprestación directa.</p></div><div class="viz"><div class="eyebrow">Empresa ↔ actores de la economía</div><div class="flow-layout"><button class="flow-node" type="button" data-flow="hogares" aria-pressed="true"><strong>Hogares</strong><small>Trabajo y consumo</small></button><button class="flow-node" type="button" data-flow="exterior" aria-pressed="false"><strong>Exterior</strong><small>Productos y máquinas</small></button><button class="flow-node" type="button" data-flow="estado" aria-pressed="false"><strong>Estado</strong><small>Servicios e impuestos</small></button><button class="flow-node" type="button" data-flow="bancos" aria-pressed="false"><strong>Sistema financiero</strong><small>Ahorro y crédito</small></button></div><div class="flow-explain" id="flow-result" aria-live="polite"></div></div></div>
<section class="section"><h2>De los recursos al ingreso</h2>${table(['Recurso o función','Ejemplo','Remuneración asociada'],[['Trabajo','Cultivo, transformación, ventas y transporte.','Salarios y otras remuneraciones laborales.'],['Tierra y recursos naturales','Suelo y recursos utilizados en el cultivo.','Renta de la tierra.'],['Capital físico','Secadora, maquinaria y bodega.','Rendimiento o alquiler del capital.'],['Organización empresarial','Coordinar recursos y asumir incertidumbre.','Beneficio residual; también puede ser negativo.']])}${note('<strong>Dinero y capital físico.</strong> Un préstamo financia una máquina; la máquina es el recurso productivo. El interés remunera el préstamo. Las categorías introductorias no coinciden exactamente con todas las partidas de cuentas nacionales.')}<div class="steps"><article class="step"><h3>Sector primario</h3><p>Cultivo y cosecha del cacao.</p></article><article class="step"><h3>Sector secundario</h3><p>Transformación del cacao en chocolate.</p></article><article class="step"><h3>Sector terciario</h3><p>Transporte, seguros, comercialización y financiación.</p></article></div></section>
<section class="section"><span class="index">EXPERIMENTO 04</span><h2>Sumar ventas cuenta el cacao varias veces.</h2><p>En esta cadena ficticia se omiten otros insumos, inventarios e impuestos. Las cifras tienen la misma unidad monetaria.</p>${table(['Etapa','Venta','Compra intermedia','Valor agregado'],[['Cultivo','100','0','100'],['Transformación','180','100','80'],['Comercialización*','250','180','70']])}<div class="stat-cards"><div class="stat-card"><small>Suma de ventas</small><strong>530</strong><small>Incluye transacciones intermedias.</small></div><div class="stat-card"><small>Valor agregado total</small><strong>250</strong><small>100 + 80 + 70</small></div><div class="stat-card"><small>Venta final</small><strong>250</strong><small>Coincide con el valor agregado.</small></div></div><p class="caption">*Para explicar la doble contabilización se muestran compras y reventas. En cuentas nacionales, la producción del comercio se registra por su margen.</p>
${quiz('q-va','¿Cuál es el aporte total de esta cadena, sin impuestos, al valor agregado?',['530, porque hay que sumar todas las ventas.','250, porque se descuentan los consumos intermedios.','70, porque solo cuenta la comercialización.'],1,'100 + (180 − 100) + (250 − 180) = 250. Sumar todas las ventas contaría varias veces el mismo producto.')}</section>
<section class="section"><span class="index">EXPERIMENTO 05</span><h2>¿Por qué se restan las importaciones?</h2><p>PIB = C + I + G + X − M. Se resta producción extranjera ya incluida en los gastos. La identidad contable no afirma que importar sea perjudicial.</p><div class="lab"><div class="controls"><p><strong>Economía ficticia:</strong> C = 500, I = 150, G = 200, X = 100, M = 80.</p>${slider('import','Compra adicional de consumo importado',0,100,0,10)}<p class="caption">Misma unidad monetaria. La compra aumenta simultáneamente C y M. Todo lo demás permanece constante.</p></div><div class="viz"><span class="eyebrow">PIB por el enfoque del gasto</span><div class="stat-row"><div class="stat"><b id="gdp-result">870</b><span>PIB resultante</span></div><div class="stat"><b id="import-result">0</b><span>cambio del PIB</span></div></div><p id="gdp-equation" aria-live="polite"></p></div></div>${details('Qué significan las letras','C: consumo privado. I: formación bruta de capital, incluida inversión pública. G: consumo final del gobierno. X: exportaciones. M: importaciones. Un préstamo es una operación financiera y no se suma automáticamente como producción.')}</section>
<section class="section"><span class="tag real">Informe real · DANE</span><h2>El dato nacional y sus límites</h2><p>El PIB real de Colombia creció <strong>3,5% anual en el segundo trimestre de 2026</strong>, según el comunicado preliminar del DANE del 18 de agosto. Este dato no implica que cada actividad, empresa u hogar haya mejorado en esa proporción.</p>${source('pib','Consultar comunicado PIB II trimestre de 2026')}<div class="buttons"><a class="btn" href="#observatorio">Leer los datos con contexto</a><a class="btn secondary" href="#sesion-4">Seguir al comercio →</a></div><p><strong>Lectura del programa:</strong> Smith, libro I, capítulos I–III de <em>La riqueza de las naciones</em>, y comunicado del PIB II trimestre de 2026.</p></section>`;}

function session4(){return hero('Sesión 04 / 25 septiembre 2026','Intercambiar puede ampliar las posibilidades.','Calcula lo que cada economía sacrifica, acuerda un precio y observa cómo se reparten las ganancias. La ventaja absoluta no cuenta toda la historia.','Resultado: explicar ganancias y límites del comercio')+`
<span class="tag sim">Dos economías ficticias · A y B</span><p>Cada economía tiene 120 horas. A necesita menos tiempo para producir ambos bienes, pero B sacrifica menos cacao al producir una máquina.</p>${table(['Horas para producir una unidad','Economía A','Economía B'],[['Cacao','2 horas','4 horas'],['Máquina de empaque','6 horas','8 horas'],['Costo de oportunidad de 1 máquina','3 unidades de cacao','2 unidades de cacao']])}
<div class="lab"><div class="controls"><span class="index">EXPERIMENTO 06</span><h2>Negocia el precio<br>del intercambio.</h2><p>A produce 60 cacao; B produce 15 máquinas. A compra 10 máquinas a B. Cambia cuántas unidades de cacao entrega por cada máquina.</p>${slider('price','Cacao por 1 máquina',1.5,3.5,2.5,.1)}<div class="result" id="trade-result" aria-live="polite"></div></div><div class="viz"><span class="eyebrow">Cambio en cacao frente a la situación inicial</span><div class="stat-row"><div class="stat"><b id="gain-a">+5</b><span>economía A</span></div><div class="stat"><b id="gain-b">+5</b><span>economía B</span></div></div><svg viewBox="0 0 500 145" role="img" aria-labelledby="trade-title trade-desc"><title id="trade-title">Distribución del cacao entre economías</title><desc id="trade-desc"></desc><text x="0" y="23" fill="white" font-size="14">60 unidades de cacao en total</text><rect x="0" y="42" width="490" height="37" rx="4" fill="#7b8893"/><rect id="trade-bar" x="0" y="42" height="37" fill="#c20e1a"/><text id="trade-a-label" x="0" y="110" fill="white" font-size="15"></text><text id="trade-b-label" x="300" y="110" fill="white" font-size="15"></text></svg><p>Las máquinas consumidas se mantienen en 10 para A y 5 para B. El precio distribuye el cacao.</p></div></div>
${table(['Consumo','Sin intercambio','Después de intercambiar'],[['Economía A','30 cacao y 10 máquinas','<span id="a-consumption"></span>'],['Economía B','20 cacao y 5 máquinas','<span id="b-consumption"></span>']])}<p class="caption">Ambas combinaciones iniciales usan 120 horas. Supuestos: costos constantes, pleno empleo y ausencia de barreras y costos de transporte. A se especializa en cacao y B en máquinas. Elaboración didáctica.</p>
${note('<strong>La ventana de ganancias mutuas.</strong> Con un precio mayor que 2 y menor que 3 unidades de cacao por máquina, ambas economías mejoran respecto a la referencia. En los extremos una es indiferente. Fuera del intervalo, una pierde con este intercambio.')}
${quiz('q-trade','A es más productiva en ambos bienes. ¿Por qué podría importar máquinas de B?',['Porque la productividad no tiene importancia.','Porque B tiene menor costo de oportunidad al producir máquinas.','Porque toda importación garantiza beneficios a todos.'],1,'En B una máquina cuesta 2 cacao y en A cuesta 3. A puede obtener máquinas a un costo relativo menor mediante el intercambio, bajo los supuestos del modelo.')}
<section class="section"><h2>Del modelo a una decisión real</h2><div class="concept-grid"><article class="concept"><h3>Costos logísticos</h3><p>Transporte, tiempos y coordinación pueden reducir el beneficio de comerciar. Añade esos costos a la comparación.</p></article><article class="concept"><h3>Distribución</h3><p>Un país puede obtener ganancias agregadas mientras ciertos trabajadores y empresas enfrentan costos de ajuste.</p></article><article class="concept"><h3>Capacidades</h3><p>La educación, la infraestructura y la tecnología pueden cambiar los costos relativos y las posibilidades de producir.</p></article></div>${details('¿Las exportaciones son lo mismo que el bienestar?','Exportar genera oportunidades, pero su valor bruto no mide por sí solo el valor agregado local, las condiciones laborales ni los impactos ambientales. Necesitamos más indicadores.')}${details('¿Un arancel beneficia a toda la economía?','Un arancel puede proteger a algunos productores y encarecer insumos o bienes para otros. La incidencia depende de competencia, precios y respuestas. Distingue los actores antes de evaluar el balance.')}</section>
<section class="section"><span class="index">MESA DE DISCUSIÓN</span><h2>Cuatro actores, una política.</h2><p>Debatan una propuesta hipotética de elevar un arancel a las máquinas de empaque. Cada equipo asume un rol: empresa exportadora, trabajador, importador o autoridad pública.</p><div class="steps"><div class="step"><h3>Identifica</h3><p>Un beneficio posible, un costo y quién lo asumiría.</p></div><div class="step"><h3>Contrasta</h3><p>Qué datos permitirían estimar el efecto y qué supuesto puede fallar.</p></div><div class="step"><h3>Argumenta</h3><p>Escribe 120 palabras separando hechos, hipótesis y valoraciones.</p></div></div><p><strong>Lectura del programa:</strong> Krugman, <em>Fundamentos de economía</em>, capítulo 19. Verifica el tema y la numeración en la edición que utilices.</p><div class="buttons"><a class="btn" href="#observatorio">Conectar con la actualidad →</a><a class="btn secondary" href="#metodo">Preparar mi argumento</a></div></section>`;}

function observatory(){return hero('Observatorio / Datos e informes','Un número necesita contexto.','Antes de compartir un titular, identifica qué se midió, en qué período, con qué unidad y frente a qué comparación. Estas fichas conectan la evidencia con preguntas económicas.','Corte de consulta: 10 septiembre 2026')+`
<section><span class="tag real">Colombia · DANE · Datos preliminares</span><h2>El PIB no tiene una sola tasa de crecimiento.</h2><div class="stat-cards"><div class="stat-card"><small>Crecimiento anual</small><strong>3,5%</strong><small>II trimestre 2026 / II trimestre 2025. Serie original.</small></div><div class="stat-card"><small>Crecimiento semestral</small><strong>2,9%</strong><small>Enero–junio 2026 / enero–junio 2025. Serie original.</small></div><div class="stat-card"><small>Crecimiento trimestral</small><strong>1,3%</strong><small>II / I trimestre 2026. Serie ajustada por estacionalidad y calendario.</small></div></div><p class="caption">Crecimiento real: series encadenadas de volumen, referencia 2015. Publicación: 18 de agosto de 2026. Cifras preliminares y sujetas a revisión.</p>${table(['Actividades seleccionadas','Variación anual real'],[['Agricultura, ganadería, caza, silvicultura y pesca','−2,1%'],['Explotación de minas y canteras','4,2%'],['Industrias manufactureras','2,0%'],['Comercio, reparación, transporte, alojamiento y comida*','2,2%']])}<p class="caption">*Nombre abreviado del agregado del DANE. Las tasas no son participaciones y no se suman para obtener el crecimiento total.</p>${source('pib','DANE · comunicado, páginas 1 y 4')}${details('Pregunta de lectura: ¿creció 3,5% la empresa de cacao?','No puede deducirse del PIB nacional. Se requieren datos de la empresa, su producto y su territorio. El agregado describe un contexto, no el comportamiento de cada unidad.')}</section>
<section class="section"><span class="tag real">Colombia · DANE-DIAN · Cifras provisionales</span><h2>La composición de lo que exportamos</h2><p>Julio de 2026: <strong>USD 4.690,7 millones FOB</strong>, una variación anual de <strong>5,9%</strong> frente a julio de 2025.</p><label for="export-mode"><strong>Explorar el gráfico por</strong></label> <select id="export-mode"><option value="share">Participación en el total (%)</option><option value="value">Valor (millones de USD FOB)</option></select><div id="export-chart" class="chart-bars" role="group" aria-label="Composición de las exportaciones"></div><p class="caption" id="export-caption"></p>${table(['Grupo','Variación anual del valor'],exportsData.map(d=>[d.name,nf.format(d.growth)+'%']))}${source('expo','DANE-DIAN · exportaciones de julio 2026, tabla 1, página 3')}
${quiz('q-data','Combustibles representa 40,0% y crece 8,3%. ¿Qué diferencia hay?',['Ambos números indican cuánto creció el grupo.','40,0% es participación; 8,3% es variación frente al año anterior.','40,0% es su participación en el PIB.'],1,'La participación divide el valor del grupo por el total exportado. La variación compara el valor del mismo grupo entre dos períodos. Ninguna equivale a su peso en el PIB.')}</section>
<section class="section"><span class="index">ACTUALIDAD COMENTADA</span><h2>Noticias para discutir en clase</h2><article class="news"><div class="date">OMC · 31 de julio de 2026 · Comercio mundial</div><h3>El valor y el volumen cuentan historias distintas</h3><p class="lead">En el primer trimestre de 2026, el comercio mundial de mercancías creció 3,2% interanual en volumen y 11% en valor.</p><p>La OMC relaciona su evolución con bienes asociados a inteligencia artificial y advierte sobre perturbaciones en Oriente Medio. Los datos de un trimestre no describen por sí solos el año completo.</p><p><strong>Para Comercio Exterior:</strong> distingue el aumento de cantidades del efecto de precios y composición.</p><p class="question"><strong>Pregunta:</strong> ¿por qué no podemos afirmar que se transportaron 11% más toneladas?</p>${source('omc','Leer la noticia en la OMC')}</article><article class="news"><div class="date">OMC · Marzo de 2026 · Informe de perspectivas</div><h3>Una proyección es un escenario, no un hecho consumado</h3><p>El escenario base de marzo estimó un crecimiento de 1,9% del volumen del comercio mundial de mercancías para 2026. La noticia de julio recuerda esa previsión. Sus supuestos y horizonte deben acompañar cualquier comparación.</p><p><strong>Pregunta:</strong> ¿qué información nueva podría cambiar una previsión de comercio?</p>${source('gtos','Consultar Global Trade Outlook and Statistics')}</article><article class="news"><div class="date">UNCTAD · Review of Maritime Transport 2025 · Contexto logístico</div><h3>El transporte marítimo conecta las decisiones</h3><p>Alrededor del 80% del volumen del comercio internacional de bienes se transporta por mar, según UNCTAD. El informe estudia puertos, fletes y vulnerabilidades. La proporción se refiere a volumen, no a valor.</p><p><strong>Pregunta:</strong> ¿cómo cambiaría la decisión del envío en la sesión 2 si aumenta el tiempo de tránsito?</p>${source('unctad','Consultar el informe y sus ediciones')}</article></section>${note('<strong>Estas fichas tienen fecha de corte.</strong> Son una selección para aprender a leer evidencia, no un servicio de noticias en tiempo real. Consulta el enlace original antes de reutilizar una cifra.')}<a class="btn" href="#metodo">Construir una ficha de evidencia →</a>`;}

