function library(){return hero('Biblioteca / Lecturas con propósito','Lee para responder una pregunta.','Una selección que acompaña las sesiones. Comienza por las lecturas del programa y usa CORE para ampliar con acceso gratuito; no necesitas comprar todos los libros.','6 libros · Lecturas básicas y complementarias')+`<div class="book-grid">${books.map(b=>`<article class="book"><div class="book-spine" aria-hidden="true"></div><div><span class="tag">${b[2]}</span><h2>${b[1]}</h2><p class="author">${b[0]}</p><p class="caption">${b[3]}</p><p>${b[4]}</p><p><strong>Pregunta de lectura</strong><br>${b[5]}</p>${link(b[6],b[7])}</div></article>`).join('')}</div><section class="section"><h2>Una ruta de lectura por sesión</h2><div class="steps"><div class="step"><h3>Antes de clase</h3><p>Identifica una idea central y escribe una pregunta que no puedas responder todavía.</p></div><div class="step"><h3>En el laboratorio</h3><p>Usa esa idea para interpretar un resultado del simulador. Escribe qué supuesto se necesita.</p></div><div class="step"><h3>Después de clase</h3><p>Busca un contraejemplo o una situación real donde el resultado podría cambiar.</p></div></div>${note('<strong>Ediciones y capítulos.</strong> Las referencias del programa se mantienen. La ficha de Reverté fecha la tercera edición en 2014, mientras el programa cita 2015. Verifica el índice de tu ejemplar antes de asignar páginas. Las recomendaciones y preguntas son propuestas pedagógicas.')}<a class="btn" href="#metodo">Abrir la caja de herramientas →</a></section>`;}

function method(){return hero('Caja de herramientas / Método','Del dato al argumento.','Una buena explicación económica muestra su evidencia, hace visibles sus supuestos y reconoce sus límites. Usa esta ruta para trabajar con cualquier noticia del curso.','Herramientas de consulta y trabajo')+`
<div class="steps"><div class="step"><h3>Pregunta</h3><p>Delimita qué quieres explicar, para quién y en qué período.</p></div><div class="step"><h3>Modela</h3><p>Define variables, relaciones y condiciones que mantienes constantes.</p></div><div class="step"><h3>Contrasta</h3><p>Busca evidencia y considera explicaciones alternativas antes de concluir.</p></div></div>
<section class="section"><h2>Tu ficha de evidencia</h2><p>Completa la ficha y descarga tus notas. Se mantienen solo mientras esta página permanezca abierta; no se envían a la docente ni a un servidor.</p><form class="method-sheet" id="evidence-form"><label for="question">Pregunta económica<textarea id="question" name="Pregunta" placeholder="¿Qué quiero explicar?"></textarea></label><label for="evidence">Dato, período, unidad y comparación<textarea id="evidence" name="Evidencia" placeholder="Qué se mide y respecto a qué se compara."></textarea></label><label for="source-notes">Fuente y fecha de publicación<textarea id="source-notes" name="Fuente" placeholder="Institución, título y enlace."></textarea></label><label for="argument">Mi explicación y su límite<textarea id="argument" name="Argumento" placeholder="El dato sugiere… bajo el supuesto… no permite concluir…"></textarea></label><button type="submit" class="btn">Descargar mi ficha (.txt)</button><p class="feedback" id="download-feedback" role="status"></p></form></section>
<section class="section"><h2>Glosario para volver cuando lo necesites</h2><div class="glossary">${[
 ['Ceteris paribus','Supuesto que mantiene otros factores constantes para estudiar una relación. En la práctica, comprueba cuáles podrían cambiar.'],['Variable y modelo','Una variable puede tomar valores distintos. Un modelo representa relaciones y simplifica la realidad para responder una pregunta.'],['Microeconomía y macroeconomía','La microeconomía estudia decisiones e interacciones de hogares, empresas y mercados. La macroeconomía analiza agregados como producción, empleo e inflación.'],['Positivo y normativo','Lo positivo formula afirmaciones contrastables. Lo normativo incorpora juicios sobre lo deseable. Economía política no es sinónimo de economía normativa.'],['Costo hundido','Gasto ya realizado que no se recupera al cambiar de decisión. No debe decidir por sí solo una comparación de beneficios y costos futuros.'],['Valor agregado','Producción menos bienes y servicios intermedios consumidos. Evita contar repetidamente los insumos a lo largo de una cadena.'],['PIB y bienestar','El PIB mide producción. Para evaluar bienestar se requieren también distribución, salud, ambiente y otras dimensiones.'],['Valor y volumen','El valor monetario depende de cantidades, precios y composición. Un cambio de valor no equivale necesariamente a un cambio de cantidad física.'],['Participación y variación','La participación es una parte del total. La variación compara una magnitud entre períodos. Ambas pueden expresarse en %, pero responden preguntas distintas.'],['Porcentaje y puntos porcentuales','Pasar de 20% a 25% equivale a 5 puntos porcentuales y a un aumento relativo del 25%. Señala cuál estás usando.'],['FOB','Valoración de los bienes hasta la frontera de salida, sin flete y seguro internacionales posteriores. Aquí se usa como concepto estadístico.'],['Ventaja comparativa','Menor costo de oportunidad en producir un bien. Se distingue de la ventaja absoluta, que compara productividad directa.'],['Balanza comercial','Diferencia entre exportaciones e importaciones de bienes con período y valoración comparables. Las exportaciones solas no permiten calcularla.'],['Correlación y causalidad','Dos variables pueden moverse juntas por otros factores. Una relación causal necesita un argumento y evidencia adicionales.']
].map(x=>details(...x)).join('')}</div></section>
<section class="section"><h2>Reto integrador: comité de exportación</h2><p>En grupos de 3 o 4, formulen una recomendación de 150 palabras para Pacífico Cacao. Incluyan una decisión productiva, un cálculo logístico, dos datos con sus fuentes y una incertidumbre. Expliquen una consecuencia para un actor distinto de la empresa.</p>${table(['Criterio','Qué debe mostrar tu trabajo'],[['Conceptos','Usa costo de oportunidad, flujos o ventaja comparativa correctamente.'],['Cálculos','Explica operaciones y conserva unidades.'],['Evidencia','Identifica fuente, período, comparación y estatus de la cifra.'],['Argumentación','Conecta la evidencia con la conclusión y reconoce límites.']])}<p class="caption">Autoevaluación: 0 = ausente o incorrecto; 1 = parcial; 2 = correcto y explicado. Esta rúbrica orienta retroalimentación y no modifica las ponderaciones del programa.</p></section>
<section class="section"><h2>Fuentes y uso de la imagen institucional</h2><p>Contenidos alineados con el programa de Fundamentos de Economía y Comercio 2026-2 y S2 de la profesora Diana Lorena Pineda Ospina. Los originales no se reproducen aquí. Las cifras de los simuladores son didácticas; las fichas estadísticas enlazan los informes oficiales.</p>${source('pib','DANE · PIB II trimestre 2026')}${source('expo','DANE-DIAN · exportaciones julio 2026')}${source('omc','OMC · noticia del 31 de julio 2026')}${source('gtos','OMC · perspectivas de marzo 2026')}${source('unctad','UNCTAD · transporte marítimo')}${source('core','CORE Econ · libro abierto')}${source('manual','Manual de identidad visual enlazado por Univalle')}<p class="caption">Firma horizontal oficial, sin redibujar ni alterar proporciones; referencia de color y tipografía del manual, especialmente páginas 30 y 43–47. Material de apoyo docente; no sustituye el portal institucional. Corte de consulta: 10 de septiembre de 2026.</p></section>`;}

const routes={'sesion-2':session2,'sesion-3':session3,'sesion-4':session4,observatorio:observatory,biblioteca:library,metodo:method};
function setText(id,value){const el=document.getElementById(id);if(el)el.textContent=value;}
function bindQuiz(){document.querySelectorAll('.quiz').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const selected=form.querySelector('input:checked');if(!selected)return;const correct=selected.value===form.dataset.answer;const f=form.querySelector('.feedback');f.textContent=(correct?'Correcto. ':'Revisa tu razonamiento. ')+form.dataset.explanation;f.className='feedback '+(correct?'good':'bad');}));}
function updateFrontier(){const hours=+$('#hours').value;$('#chocolate').max=hours/4;const r=frontier(hours,+$('#chocolate').value);$('#chocolate').value=r.chocolate;setText('hours-label',nf.format(hours)+' h');setText('chocolate-label',nf.format(r.chocolate));setText('chocolate-max',nf.format(r.maxChocolate));setText('cacao-result',nf.format(r.cacao));setText('choco-result',nf.format(r.chocolate));$('#frontier-result').innerHTML='<strong>1 chocolate cuesta 2 cacao.</strong>Elegiste '+nf.format(r.chocolate)+' chocolate y '+nf.format(r.cacao)+' cacao. Usas '+hours+' horas.';const x=65+r.cacao*4.5,y=260-r.chocolate*5;const end=65+r.maxCacao*4.5,top=260-r.maxChocolate*5;$('#frontier-line').setAttribute('d',`M65 ${top}L${end} 260`);$('#frontier-area').setAttribute('d',`M65 260V${top}L${end} 260Z`);$('#frontier-guide').setAttribute('d',`M65 ${y}H${x}V260`);$('#frontier-dot').setAttribute('cx',x);$('#frontier-dot').setAttribute('cy',y);setText('fpp-desc',`Con ${hours} horas puedes producir hasta ${r.maxCacao} cacao o ${r.maxChocolate} chocolate. La selección actual es ${r.cacao} cacao y ${r.chocolate} chocolate.`);}
function updateFreight(){const daily=+$('#daily').value;const r=freight(daily);setText('daily-label',nf.format(daily)+' USD');setText('freight-a',nf.format(r.a));setText('freight-b',nf.format(r.b));const saving=Math.abs(r.a-r.b);$('#freight-result').innerHTML=`<strong>${r.a===r.b?'Ambas cuestan lo mismo.':`La opción ${r.a<r.b?'A':'B'} cuesta menos.`}</strong>${saving?`Ahorro total: USD ${nf.format(saving)}.`:'En el umbral el costo total es idéntico.'}`;}
const flows={hogares:'<h3>Trabajo y salario</h3><p><strong>Real:</strong> los hogares aportan trabajo a la empresa.<br><strong>Monetario:</strong> la empresa paga salarios a los hogares.</p><p>Al consumir chocolate, el producto va al hogar y el pago vuelve a la empresa.</p>',exterior:'<h3>Exportar e importar</h3><p><strong>Real:</strong> sale chocolate hacia el cliente exterior y entra una máquina a la empresa.<br><strong>Monetario:</strong> entra el pago de exportación y sale el pago de la máquina.</p>',estado:'<h3>Impuestos y servicios</h3><p>La empresa paga impuestos. El Estado provee servicios e infraestructura. No existe una contraprestación individual equivalente por cada impuesto.</p><p>Una transferencia monetaria pública tampoco implica un bien entregado directamente a cambio.</p>',bancos:'<h3>Ahorro y financiación</h3><p>El ahorro y el crédito conectan a quienes aportan fondos y quienes requieren financiación. La empresa recibe un préstamo y después paga capital e intereses.</p><p>El préstamo es un flujo financiero; no es por sí mismo un bien producido.</p>'};
function updateGDP(){const extra=+$('#import').value;setText('import-label',nf.format(extra));setText('gdp-result',gdp(500+extra,150,200,100,80+extra));setText('gdp-equation',`${500+extra} + 150 + 200 + 100 − ${80+extra} = 870. El consumo y las importaciones suben en la misma cantidad.`);}
function updateTrade(){const price=+$('#price').value,r=trade(price);setText('price-label',nf.format(price));setText('gain-a',(r.aGain>0?'+':'')+nf.format(r.aGain));setText('gain-b',(r.bGain>0?'+':'')+nf.format(r.bGain));setText('a-consumption',`${nf.format(r.aCacao)} cacao y 10 máquinas`);setText('b-consumption',`${nf.format(r.bCacao)} cacao y 5 máquinas`);setText('trade-a-label',`A: ${nf.format(r.aCacao)} cacao`);setText('trade-b-label',`B: ${nf.format(r.bCacao)} cacao`);$('#trade-bar').setAttribute('width',490*r.aCacao/60);setText('trade-desc',`Después del intercambio A consume ${r.aCacao} cacao y 10 máquinas; B consume ${r.bCacao} cacao y 5 máquinas.`);$('#trade-result').innerHTML=`<strong>${r.bothGain?'Ambas economías ganan.':price===2||price===3?'Una gana y otra queda igual.':`La economía ${price<2?'B':'A'} pierde cacao.`}</strong>A entrega ${nf.format(price*10)} cacao por 10 máquinas. Compara con la situación inicial.`;}
function exportChart(){const mode=$('#export-mode').value;const max=mode==='share'?100:2000;$('#export-chart').innerHTML=exportsData.map(d=>`<div class="bar-row"><div class="bar-top"><span>${d.name}</span><strong>${nf.format(d[mode])}${mode==='share'?'%':''}</strong></div><div class="track"><div class="bar" style="width:${100*d[mode]/max}%"></div></div></div>`).join('');setText('export-caption',mode==='share'?'Base: valor FOB total exportado en julio de 2026. La suma es 100,1% por redondeo. Otros sectores incluye oro no monetario y productos no clasificados en los demás grupos.':'Millones de USD FOB, julio de 2026. Los componentes redondeados pueden diferir del total. FOB excluye flete y seguro internacionales posteriores a la frontera de salida.');}
function render(focus=false){const route=location.hash.slice(1)||'sesion-2';const valid=routes[route]?route:'sesion-2';$('#contenido').innerHTML=routes[valid]();$('#contenido').classList.remove('flash');void $('#contenido').offsetWidth;$('#contenido').classList.add('flash');document.querySelectorAll('[data-route]').forEach(el=>{if(el.dataset.route===valid)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});document.title=`${{'sesion-2':'Decidir y elegir','sesion-3':'Conectar la economía','sesion-4':'Intercambiar',observatorio:'Observatorio',biblioteca:'Biblioteca',metodo:'Caja de herramientas'}[valid]} · Laboratorio de economía y comercio`;bindQuiz();if(valid==='sesion-2'){['hours','chocolate'].forEach(id=>document.getElementById(id).addEventListener('input',updateFrontier));$('#reset-frontier').addEventListener('click',()=>{$('#hours').value=120;$('#chocolate').value=15;updateFrontier();});$('#daily').addEventListener('input',updateFreight);updateFrontier();updateFreight();}if(valid==='sesion-3'){$('#flow-result').innerHTML=flows.hogares;document.querySelectorAll('[data-flow]').forEach(el=>el.addEventListener('click',()=>{document.querySelectorAll('[data-flow]').forEach(b=>b.setAttribute('aria-pressed','false'));el.setAttribute('aria-pressed','true');$('#flow-result').innerHTML=flows[el.dataset.flow];}));$('#import').addEventListener('input',updateGDP);updateGDP();}if(valid==='sesion-4'){$('#price').addEventListener('input',updateTrade);updateTrade();}if(valid==='observatorio'){$('#export-mode').addEventListener('change',exportChart);exportChart();}if(valid==='metodo'){document.querySelectorAll('#evidence-form textarea').forEach(el=>{el.value=evidenceDraft[el.name]||'';el.addEventListener('input',()=>{evidenceDraft[el.name]=el.value;});});$('#evidence-form').addEventListener('submit',e=>{e.preventDefault();const entries=[...new FormData(e.currentTarget)];if(entries.every(([,v])=>!String(v).trim())){setText('download-feedback','Escribe al menos una idea antes de descargar tu ficha.');return;}const text='MI FICHA DE EVIDENCIA\nLaboratorio de economía y comercio\n\n'+entries.map(([k,v])=>k+'\n'+v).join('\n\n');const blob=new Blob([text],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='mi-ficha-economia.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setText('download-feedback','Tu ficha está lista para descargar. Conserva el archivo antes de salir.');});}if(focus){$('#contenido').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
window.addEventListener('hashchange',()=>render(true));render();
